// boss_fill.cpp: the right parameter for each job.
#include <iostream>
#include <memory>
#include <string>

struct Robot {
    std::string name;
    ~Robot() { std::cout << "scrap " << name << '\n'; }
};

void inspect(const Robot& r) { std::cout << "inspect " << r.name << '\n'; }

void upgrade(std::unique_ptr<Robot>& slot) {
    slot = std::make_unique<Robot>("Bolt II");
}

void retire(std::unique_ptr<Robot> r) { std::cout << "retire " << r->name << '\n'; }

int main() {
    auto bay{std::make_unique<Robot>("Bolt")};
    inspect(*bay);
    upgrade(bay);
    retire(std::move(bay));
    std::cout << "bay is " << (bay ? "full" : "empty") << '\n';
}

