// fill_span.cpp: one function for a C array and a vector.
#include <iostream>
#include <span>
#include <vector>

int largest(std::span<const int> xs) {
    int best{xs[0]};
    for (int x : xs) {
        if (x > best) {
            best = x;
        }
    }
    return best;
}

int main() {
    int temps[4]{12, 19, 7, 15};
    std::vector<int> more{3, 21, 8};
    std::cout << largest(temps) << ' ' << largest(more) << '\n';
}

