// pass_three.cpp: three ways to hand a pet to a function.
#include <iostream>
#include <memory>
#include <string>

struct Pet {
    std::string name;
    explicit Pet(std::string n) : name{std::move(n)} {
        std::cout << "  [hello " << name << "]\n";
    }
    ~Pet() { std::cout << "  [goodbye " << name << "]\n"; }
};

// just use it: no card involved
void brush(Pet& p) { std::cout << "brushing " << p.name << '\n'; }

// reseat the caller's card: put a new pet on it
void swap_in(std::unique_ptr<Pet>& slot) {
    slot = std::make_unique<Pet>("Mochi");
}

// take the card for good
void adopt(std::unique_ptr<Pet> p) {
    std::cout << "adopted " << p->name << '\n';
}

int main() {
    auto card{std::make_unique<Pet>("Biscuit")};
    brush(*card);
    swap_in(card);
    brush(*card);
    adopt(std::move(card));
    std::cout << "card is " << (card ? "full" : "empty") << '\n';
}

