    auto mum{std::make_shared<Parent>("Ada")};
    auto kid{std::make_shared<Child>("Bea")};
    kid->parent = mum;
    mum->kids.push_back(kid);
    std::cout << kid->name << "'s parent is " << kid->parent->name << std::endl;
}

