// trace_weak.cpp: a neighbour watches the sheet.
#include <iostream>
#include <memory>

void show(int step, const std::weak_ptr<int>& w) {
    std::cout << step << ' ' << w.use_count() << ' ' << std::boolalpha << w.expired() << '\n';
}

int main() {
    auto a{std::make_shared<int>(5)};
    std::weak_ptr<int> w{a};
    show(1, w);
    auto b{a};
    show(2, w);
    a.reset();
    show(3, w);
    auto c{w.lock()};
    show(4, w);
    b.reset();
    show(5, w);
    c.reset();
    show(6, w);
}

