// weak_fix.cpp: the buddy link only checks; it doesn't sign the sheet.
#include <iostream>
#include <memory>
#include <string>

struct Pet {
    std::string name;
    std::weak_ptr<Pet> buddy;
    explicit Pet(std::string n) : name{std::move(n)} {}
    ~Pet() { std::cout << "goodbye " << name << std::endl; }
};

int main() {
    auto a{std::make_shared<Pet>("Biscuit")};
    auto b{std::make_shared<Pet>("Mochi")};
    a->buddy = b;
    b->buddy = a;
    std::cout << "a: " << a.use_count() << ", b: " << b.use_count() << std::endl;
    if (auto friend_of_a = a->buddy.lock()) {
        std::cout << "a's buddy is " << friend_of_a->name << std::endl;
    }
}
